398	/// The kind of block a top-level statement makes, or `None` when it is not one.
399	fn statement_kind(statement: &Statement<'_>) -> Option<SymbolKind> {
400	    match statement {
401	        Statement::FunctionDeclaration(_) => Some(SymbolKind::Function),
402	        Statement::ClassDeclaration(_) => Some(SymbolKind::Class),
403	        Statement::TSInterfaceDeclaration(_) => Some(SymbolKind::Interface),
404	        Statement::TSTypeAliasDeclaration(_) => Some(SymbolKind::TypeAlias),
405	        Statement::TSEnumDeclaration(_) => Some(SymbolKind::Enum),
406	        Statement::VariableDeclaration(_) => Some(SymbolKind::Variable),
407	        Statement::ExportDeclaration(export) => {
408	            Some(declaration_kind(&export.declaration).unwrap_or(SymbolKind::Other))
409	        }
410	        Statement::ImportDeclaration(_)
411	        | Statement::ExportNamedDeclaration(_)
412	        | Statement::ExportFromDeclaration(_)
413	        | Statement::ExportDefaultDeclaration(_)
414	        | Statement::ExportAllDeclaration(_) => Some(SymbolKind::Other),
415	        _ => None,
416	    }
417	}
