419	fn declaration_kind(decl: &Declaration<'_>) -> Option<SymbolKind> {
420	    match decl {
421	        Declaration::FunctionDeclaration(_) => Some(SymbolKind::Function),
422	        Declaration::ClassDeclaration(_) => Some(SymbolKind::Class),
423	        Declaration::TSInterfaceDeclaration(_) => Some(SymbolKind::Interface),
424	        Declaration::TSTypeAliasDeclaration(_) => Some(SymbolKind::TypeAlias),
425	        Declaration::TSEnumDeclaration(_) => Some(SymbolKind::Enum),
426	        Declaration::VariableDeclaration(_) => Some(SymbolKind::Variable),
427	        Declaration::TSExternalModuleDeclaration(_)
428	        | Declaration::TSNamespaceDeclaration(_)
429	        | Declaration::TSGlobalDeclaration(_)
430	        | Declaration::TSImportEqualsDeclaration(_) => None,
431	    }
432	}
