435	fn statement_function<'a, 'b>(statement: &'b Statement<'a>) -> Option<&'b Function<'a>> {
436	    match statement {
437	        Statement::FunctionDeclaration(function) => Some(function),
438	        Statement::ExportDeclaration(export) => match &export.declaration {
439	            Declaration::FunctionDeclaration(function) => Some(function),
440	            _ => None,
441	        },
442	        _ => None,
