454	/// Collects every JSX element in document order.
455	struct JsxCollector<'l> {
456	    lines: &'l LineIndex,
457	    found: Vec<JsxElementEntry>,
458	}
459	
460	impl<'a> Visit<'a> for JsxCollector<'_> {
461	    fn visit_jsx_element(&mut self, element: &JSXElement<'a>) {
462	        let opening = &element.opening_element;
463	        let name = jsx_element_name(&opening.name);
464	        let attributes = opening.attributes.iter().map(jsx_attribute).collect();
465	        self.found.push(JsxElementEntry {
466	            is_html: name.chars().next().is_some_and(char::is_lowercase),
467	            name,
468	            line: self.lines.line(opening.span.start),
469	            attributes,
470	        });
471	        walk::walk_jsx_element(self, element);
472	    }
473	}
474	
475	fn jsx_attribute(item: &JSXAttributeItem<'_>) -> JsxAttribute {
476	    match item {
477	        JSXAttributeItem::Attribute(attribute) => {
478	            let name = match &attribute.name {
479	                JSXAttributeName::Identifier(id) => id.name.as_str().to_owned(),
480	                JSXAttributeName::NamespacedName(ns) => format!("{}:{}", ns.namespace.name, ns.name.name),
481	            };
482	            let (string_value, is_expression) = match &attribute.value {
483	                Some(JSXAttributeValue::StringLiteral(literal)) => (Some(literal.value.as_str().to_owned()), false),
484	                Some(
485	                    JSXAttributeValue::ExpressionContainer(_)
486	                    | JSXAttributeValue::Element(_)
487	                    | JSXAttributeValue::Fragment(_),
488	                ) => (None, true),
489	                None => (None, false),
490	            };
491	            JsxAttribute { name, string_value, is_expression, is_spread: false }
492	        }
493	        JSXAttributeItem::SpreadAttribute(_) => {
494	            JsxAttribute { name: "...".to_owned(), string_value: None, is_expression: false, is_spread: true }
495	        }
496	    }
497	}
498	
499	fn jsx_element_name(name: &JSXElementName<'_>) -> String {
500	    match name {
501	        JSXElementName::Identifier(id) => id.name.as_str().to_owned(),
502	        JSXElementName::IdentifierReference(id) => id.name.as_str().to_owned(),
503	        JSXElementName::NamespacedName(ns) => format!("{}:{}", ns.namespace.name, ns.name.name),
504	        JSXElementName::MemberExpression(member) => jsx_member(member),
505	        JSXElementName::ThisExpression(_) => "this".to_owned(),
506	    }
507	}
508	
509	fn jsx_member(member: &JSXMemberExpression<'_>) -> String {
510	    let object = match &member.object {
511	        JSXMemberExpressionObject::IdentifierReference(id) => id.name.as_str().to_owned(),
512	        JSXMemberExpressionObject::MemberExpression(inner) => jsx_member(inner),
513	        JSXMemberExpressionObject::ThisExpression(_) => "this".to_owned(),
514	    };
515	    format!("{object}.{}", member.property.name)
516	}
